#[requires(!markers.value.is_empty())]
#[ensures(!ret.is_empty())]
fn vocative_kind_for_markers(markers: &WithFreeModifiers<Vec<Token>>) -> String {
    let Some(first) = markers.value.first() else {
        return "vocative".to_owned();
    };
    match first.cmavo() {
        Some(Cmavo::Coi) => "greeting".to_owned(),
        Some(Cmavo::Jehe) => "acknowledgement".to_owned(),
        Some(Cmavo::Coho) => "farewell".to_owned(),
        Some(Cmavo::Fihi) => "welcome".to_owned(),
        Some(Cmavo::Mihe) => "selfIdentification".to_owned(),
        Some(Cmavo::Doi) => "address".to_owned(),
        _ => token_text(first),
    }
}

#[requires(true)]
#[ensures(!ret.introduced_by.is_empty())]
fn scalar_negation_for_marker(marker: &WithFreeModifiers<Token>) -> ScalarNegation {
    scalar_negation_for_token(&marker.value)
}

#[requires(true)]
#[ensures(!ret.introduced_by.is_empty())]
fn scalar_negation_for_token(token: &Token) -> ScalarNegation {
    ScalarNegation::new(
        scalar_negation_kind_for_cmavo(token.cmavo()),
        token_text(token),
    )
}

#[requires(true)]
#[ensures(true)]
fn scalar_negation_for_tanru_unit(unit: &TanruUnitSyntax) -> Option<ScalarNegation> {
    match unit.as_data() {
        data!(TanruUnitSyntax::ScalarNegatedTanruUnit { nahe, .. }) => {
            Some(scalar_negation_for_marker(nahe))
        }
        data!(TanruUnitSyntax::RelativeClauses { base, .. })
        | data!(TanruUnitSyntax::LinkedSumtiTanruUnit { base, .. })
        | data!(TanruUnitSyntax::PreposedLinkedSumtiTanruUnit { base, .. })
        | data!(TanruUnitSyntax::AssignedProBridi { base, .. }) => {
            scalar_negation_for_tanru_unit(base)
        }
        _ => None,
    }
}

#[requires(true)]
#[ensures(true)]
fn scalar_negation_for_selbri(selbri: &SelbriSyntax) -> Option<ScalarNegation> {
    match selbri.as_data() {
        data!(SelbriSyntax::GroupedSelbri { selbri, .. })
        | data!(SelbriSyntax::TaggedSelbri {
            inner_selbri: selbri,
            ..
        }) => scalar_negation_for_selbri(selbri),
        data!(SelbriSyntax::Tanru(units)) if units.len() == 1 => {
            scalar_negation_for_tanru_unit(units.first())
        }
        _ => None,
    }
}

#[requires(true)]
#[ensures(ret.as_ref().is_none_or(|negation| !negation.introduced_by.is_empty()))]
fn modal_negation_for_tense_modal(tense_modal: &TenseModalSyntax) -> Option<ModalNegation> {
    match tense_modal.as_data() {
        data!(TenseModalSyntax::Composite { parts }) => {
            let mut previous_recurrence_marker = false;
            for part in &parts.value {
                let data!(CompositeTenseModalPartSyntax::Cmavo(token)) = part.as_data() else {
                    previous_recurrence_marker = false;
                    continue;
                };
                if token.cmavo() == Some(Cmavo::Nai) {
                    if !previous_recurrence_marker {
                        return Some(ModalNegation::new(
                            ModalNegationKind::Contradictory,
                            token_text(token),
                        ));
                    }
                    previous_recurrence_marker = false;
                    continue;
                }
                previous_recurrence_marker = token_is_recurrence_interval_marker(token);
            }
            None
        }
        data!(TenseModalSyntax::Modal { nai: Some(nai), .. }) => Some(ModalNegation::new(
            ModalNegationKind::Contradictory,
            token_text(&nai.value),
        )),
        _ => None,
    }
}

#[requires(true)]
#[ensures(true)]
fn token_is_recurrence_interval_marker(token: &Token) -> bool {
    matches!(
        token.cmavo(),
        Some(Cmavo::Roi | Cmavo::Rehu | Cmavo::Dihi | Cmavo::Naho | Cmavo::Ruhi | Cmavo::Tahe)
    )
}

#[requires(true)]
#[ensures(ret.as_ref().is_none_or(|negation| !negation.introduced_by.is_empty()))]
fn modal_scalar_negation_for_tense_modal(tense_modal: &TenseModalSyntax) -> Option<ScalarNegation> {
    match tense_modal.as_data() {
        data!(TenseModalSyntax::Composite { parts }) => parts.value.iter().find_map(|part| {
            let data!(CompositeTenseModalPartSyntax::Cmavo(token)) = part.as_data() else {
                return None;
            };
            matches!(
                token.cmavo(),
                Some(Cmavo::Nahe | Cmavo::Tohe | Cmavo::Nohe | Cmavo::Jeha)
            )
            .then(|| scalar_negation_for_token(token))
        }),
        data!(TenseModalSyntax::Modal {
            nahe: Some(nahe),
            ..
        }) => Some(scalar_negation_for_marker(nahe)),
        _ => None,
    }
}

#[requires(true)]
#[ensures(true)]
fn tense_modal_makes_modal_sticky(tense_modal: &TenseModalSyntax) -> bool {
    matches!(
        tense_modal.as_data(),
        data!(TenseModalSyntax::Modal { ki: Some(_), .. })
    )
}

#[requires(true)]
#[ensures(true)]
fn tense_modal_makes_tense_sticky(tense_modal: &TenseModalSyntax) -> bool {
    tense_modal.composite_ki().is_some()
        && !temporal_path_relations_for_tense_modal(tense_modal).is_empty()
}

#[requires(true)]
#[ensures(true)]
fn tense_modal_makes_space_sticky(tense_modal: &TenseModalSyntax) -> bool {
    tense_modal.composite_ki().is_some()
        && !space_path_relations_for_tense_modal(tense_modal).is_empty()
}

#[requires(true)]
#[ensures(true)]
fn tense_modal_resets_sticky_tense(tense_modal: &TenseModalSyntax) -> bool {
    matches!(tense_modal.as_data(), data!(TenseModalSyntax::Sticky(_)))
}

#[requires(true)]
#[ensures(true)]
fn selbri_resets_sticky_modals(selbri: &SelbriSyntax) -> bool {
    match selbri.as_data() {
        data!(SelbriSyntax::TaggedSelbri {
            tense_modal,
            inner_selbri,
        }) => {
            tense_modal_resets_sticky_modals(tense_modal)
                || selbri_resets_sticky_modals(inner_selbri)
        }
        data!(SelbriSyntax::GroupedSelbri {
            ke_tense_modal,
            selbri,
            ..
        }) => {
            ke_tense_modal
                .as_deref()
                .is_some_and(tense_modal_resets_sticky_modals)
                || selbri_resets_sticky_modals(selbri)
        }
        data!(SelbriSyntax::ConvertedSelbri { inner_selbri, .. })
        | data!(SelbriSyntax::Negated { inner_selbri, .. }) => {
            selbri_resets_sticky_modals(inner_selbri)
        }
        data!(SelbriSyntax::Tanru(units)) => units.iter().any(tanru_unit_resets_sticky_modals),
        data!(SelbriSyntax::InvertedTanru {
            leading_selbri,
            trailing_selbri,
            ..
        })
        | data!(SelbriSyntax::SelbriConnection {
            leading_selbri,
            trailing_selbri,
            ..
        })
        | data!(SelbriSyntax::BoundSelbriConnection {
            leading_selbri,
            trailing_selbri,
            ..
        }) => {
            selbri_resets_sticky_modals(leading_selbri)
                || selbri_resets_sticky_modals(trailing_selbri)
        }
        data!(SelbriSyntax::ForethoughtSelbriConnection {
            leading_bridi,
            trailing_bridi,
            ..
        }) => {
            main_selbri_for_bridi(leading_bridi).is_some_and(selbri_resets_sticky_modals)
                || main_selbri_for_bridi(trailing_bridi).is_some_and(selbri_resets_sticky_modals)
        }
        _ => false,
    }
}

#[requires(true)]
#[ensures(true)]
fn tanru_unit_resets_sticky_modals(unit: &TanruUnitSyntax) -> bool {
    match unit.as_data() {
        data!(TanruUnitSyntax::GroupedTanruUnit { selbri, .. })
        | data!(TanruUnitSyntax::SelbriGroupTanruUnit(selbri)) => {
            selbri_resets_sticky_modals(selbri)
        }
        data!(TanruUnitSyntax::ModalConversion {
            tense_modal,
            inner_unit,
            ..
        }) => {
            tense_modal
                .as_deref()
                .is_some_and(tense_modal_resets_sticky_modals)
                || tanru_unit_resets_sticky_modals(inner_unit)
        }
        data!(TanruUnitSyntax::ConvertedTanruUnit { inner_unit, .. })
        | data!(TanruUnitSyntax::ScalarNegatedTanruUnit { inner_unit, .. })
        | data!(TanruUnitSyntax::RelativeClauses {
            base: inner_unit,
            ..
        })
        | data!(TanruUnitSyntax::LinkedSumtiTanruUnit {
            base: inner_unit,
            ..
        })
        | data!(TanruUnitSyntax::PreposedLinkedSumtiTanruUnit {
            base: inner_unit,
            ..
        })
        | data!(TanruUnitSyntax::AssignedProBridi {
            base: inner_unit,
            ..
        }) => tanru_unit_resets_sticky_modals(inner_unit),
        data!(TanruUnitSyntax::TanruUnitConnection {
            leading_unit,
            trailing_unit,
            ..
        })
        | data!(TanruUnitSyntax::BoundTanruUnitConnection {
            leading_unit,
            trailing_unit,
            ..
        }) => {
            tanru_unit_resets_sticky_modals(leading_unit)
                || tanru_unit_resets_sticky_modals(trailing_unit)
        }
        _ => false,
    }
}

#[requires(true)]
#[ensures(true)]
fn tense_modal_resets_sticky_modals(tense_modal: &TenseModalSyntax) -> bool {
    matches!(tense_modal.as_data(), data!(TenseModalSyntax::Sticky(_)))
}

#[requires(true)]
#[ensures(true)]
fn scalar_negation_kind_for_cmavo(cmavo: Option<Cmavo>) -> ScalarNegationKind {
    match cmavo {
        Some(Cmavo::Tohe) => ScalarNegationKind::Opposite,
        Some(Cmavo::Nohe) => ScalarNegationKind::Neutral,
        Some(Cmavo::Jeha) => ScalarNegationKind::Affirmed,
        _ => ScalarNegationKind::OtherThan,
    }
}

#[requires(true)]
#[ensures(source_text.is_none() -> ret.as_slice() == spans)]
fn source_spans_with_following_cmevla_period(
    spans: &[SourceSpan],
    source_text: Option<&str>,
) -> Vec<SourceSpan> {
    let Some(source_text) = source_text else {
        return spans.to_vec();
    };
    let Some((last_index, last_span)) = spans
        .iter()
        .enumerate()
        .max_by_key(|(_, span)| span.byte_end)
    else {
        return Vec::new();
    };
    let Some(period) = source_text
        .get(last_span.byte_end..)
        .and_then(|tail| tail.chars().next())
        .filter(|period| is_lojban_period(*period))
    else {
        return spans.to_vec();
    };
    let Ok(expanded) = SourceSpan::new(
        last_span.source_id.clone(),
        last_span.byte_start,
        last_span.byte_end + period.len_utf8(),
        last_span.char_start,
        last_span.char_end + 1,
    ) else {
        return spans.to_vec();
    };
    let mut expanded_spans = spans.to_vec();
    expanded_spans[last_index] = expanded;
    expanded_spans
}

#[requires(true)]
#[ensures(ret == matches!(value, '.' | 'ӏ' | 'Ӏ' | '\u{ed89}'))]
fn is_lojban_period(value: char) -> bool {
    matches!(value, '.' | 'ӏ' | 'Ӏ' | '\u{ed89}')
}

#[requires(true)]
#[ensures(!ret.is_empty())]
fn token_text(token: &Token) -> String {
    token
        .core_word()
        .bare_word()
        .map(word_text)
        .unwrap_or_else(|| token.to_string())
}

#[requires(true)]
#[ensures(!ret.is_empty())]
fn quote_delimiter_text(token: &Token) -> String {
    match token.core_word().as_data() {
        data!(WordLike::DelimitedNonLojbanQuote {
            opening_delimiter,
            ..
        }) => word_text(opening_delimiter),
        data!(WordLike::DelimitedWordQuote { marker, .. }) => word_text(marker),
        _ => token_text(token),
    }
}

#[requires(true)]
#[ensures(!ret.is_empty())]
fn word_text(word: &Word) -> String {
    strip_diacritics(word.phonemes().as_str())
}

#[requires(!words.is_empty())]
#[ensures(!ret.is_empty())]
fn word_run_text(words: &WordRun) -> String {
    words.iter().map(token_text).collect::<Vec<_>>().join(" ")
}

#[requires(!tokens.is_empty())]
#[ensures(!ret.is_empty())]
fn token_vec_text(tokens: &[Token]) -> String {
    tokens.iter().map(token_text).collect::<Vec<_>>().join(" ")
}

#[requires(!text.is_empty())]
#[ensures(true)]
fn parse_decimal_integer(text: &str) -> Option<i64> {
    parse_simple_pa_integer(text)
}

#[requires(true)]
#[ensures(true)]
fn simple_pa_quantity_value_for_mekso(expression: &MeksoSyntax) -> Option<QuantityValue> {
    let data!(MeksoSyntax::NumberMekso(quantifier)) = expression.as_data() else {
        return None;
    };
    let data!(QuantifierSyntax::NumberQuantifier { number, .. }) = quantifier.as_data() else {
        return None;
    };
    let text = word_run_text(&number.value);
    parse_relational_pa_integer(&text)
        .map(QuantityValue::integer)
        .or_else(|| parse_simple_pa_integer(&text).map(QuantityValue::integer))
        .or_else(|| parse_simple_pa_decimal(&text).map(QuantityValue::text))
}

#[requires(!text.is_empty())]
#[ensures(true)]
fn math_literal_for_pa_text(text: String) -> MathLiteral {
    if let Some(components) = parse_mixed_radix_pa_components(&text) {
        return MathLiteral::mixed_radix(components);
    }
    parse_simple_pa_integer(&text)
        .map(MathLiteral::integer)
        .or_else(|| {
            parse_simple_pa_decimal(&text)
                .map(|decimal| MathLiteral::text("decimal".to_owned(), decimal))
        })
        .unwrap_or_else(|| MathLiteral::text("number".to_owned(), text))
}

#[requires(!text.is_empty())]
#[ensures(ret.as_ref().is_none_or(|components| components.len() >= 2))]
fn parse_mixed_radix_pa_components(text: &str) -> Option<Vec<MixedRadixComponent>> {
    let words = text.split_whitespace().collect::<Vec<_>>();
    if !words.contains(&"pi'e") {
        return None;
    }
    let mut components = Vec::new();
    let mut current = Vec::new();
    for word in words {
        if word == "pi'e" {
            if current.is_empty() {
                return None;
            }
            let component_text = current.join(" ");
            components.push(MixedRadixComponent::new(
                component_text.clone(),
                parse_simple_pa_integer(&component_text),
            ));
            current.clear();
        } else {
            current.push(word);
        }
    }
    if current.is_empty() {
        return None;
    }
    let component_text = current.join(" ");
    components.push(MixedRadixComponent::new(
        component_text.clone(),
        parse_simple_pa_integer(&component_text),
    ));
    (components.len() >= 2).then_some(components)
}

#[requires(!text.is_empty())]
#[ensures(true)]
fn parse_simple_pa_integer(text: &str) -> Option<i64> {
    let mut words = text.split_whitespace();
    let first = words.next()?;
    let (sign, first_digit) = match first {
        "ni'u" => (-1_i64, words.next()?),
        "ma'u" => (1_i64, words.next()?),
        _ => (1_i64, first),
    };
    let mut value = i64::from(pa_digit_value(first_digit)?);
    for word in words {
        let digit = i64::from(pa_digit_value(word)?);
        value = value.checked_mul(10)?.checked_add(digit)?;
    }
    Some(sign * value)
}

#[requires(!text.is_empty())]
#[ensures(true)]
fn parse_relational_pa_integer(text: &str) -> Option<i64> {
    let (prefix, rest) = text.split_once(char::is_whitespace)?;
    if !matches!(prefix, "su'o" | "su'e" | "za'u" | "me'i" | "su'a") {
        return None;
    }
    let rest = rest.trim();
    if rest.is_empty() {
        return None;
    }
    parse_simple_pa_integer(rest)
}

#[requires(!text.is_empty())]
#[ensures(ret.as_ref().is_none_or(|value| !value.is_empty()))]
fn parse_simple_pa_decimal(text: &str) -> Option<String> {
    let words = text.split_whitespace().collect::<Vec<_>>();
    let (sign, words) = match words.as_slice() {
        ["ni'u", rest @ ..] => ("-", rest),
        ["ma'u", rest @ ..] => ("", rest),
        _ => ("", words.as_slice()),
    };
    let point = words.iter().position(|word| *word == "pi")?;
    if words[point + 1..].is_empty() {
        return None;
    }
    let integer = if point == 0 {
        "0".to_owned()
    } else {
        words[..point]
            .iter()
            .map(|word| pa_digit_value(word).map(|digit| char::from(b'0' + digit)))
            .collect::<Option<String>>()?
    };
    let fraction = words[point + 1..]
        .iter()
        .map(|word| pa_digit_value(word).map(|digit| char::from(b'0' + digit)))
        .collect::<Option<String>>()?;
    Some(format!("{sign}{integer}.{fraction}"))
}

#[requires(!word.is_empty())]
#[ensures(ret.is_none_or(|digit| digit <= 9))]
fn pa_digit_value(word: &str) -> Option<u8> {
    match word {
        "no" => Some(0),
        "pa" => Some(1),
        "re" => Some(2),
        "ci" => Some(3),
        "vo" => Some(4),
        "mu" => Some(5),
        "xa" => Some(6),
        "ze" => Some(7),
        "bi" => Some(8),
        "so" => Some(9),
        _ => None,
    }
}

#[requires(true)]
#[ensures(true)]
fn word_type_is_brivla_like(word_type: WordType) -> bool {
    matches!(
        word_type,
        WordType::Gismu
            | WordType::ExperimentalGismu
            | WordType::Lujvo
            | WordType::ZeiLujvo
            | WordType::ObsoleteZeiLujvo
            | WordType::Fuivla
            | WordType::ObsoleteFuivla
    )
}

#[requires(true)]
#[ensures(true)]
fn text_has_semantic_content(text: &TextSyntax) -> bool {
    !text.leading_cmevla.is_empty()
        || !text.leading_free_modifiers.is_empty()
        || text.paragraphs.iter().any(|paragraph| {
            paragraph
                .statements
                .iter()
                .any(|statement| statement.statement.is_some())
        })
}

#[requires(true)]
#[ensures(true)]
fn bridi_contains_ko(bridi: &BridiSyntax) -> bool {
    let mut contains_ko = false;
    bridi.visit_words(&mut |token| {
        if token.cmavo() == Some(Cmavo::Ko) {
            contains_ko = true;
        }
    });
    contains_ko
}

